import json
import re
from docx import Document
from docx.oxml.ns import qn
from lxml import etree
import copy

def get_paragraph_full_text(para):
    return ''.join(run.text for run in para.runs)

def replace_in_paragraph(para, replacements):
    """Replace placeholders in a paragraph, handling split runs."""
    full_text = ''.join(run.text for run in para.runs)
    if '{{' not in full_text:
        return full_text

    new_text = full_text
    for key, value in replacements.items():
        new_text = new_text.replace('{{' + key + '}}', str(value))

    if new_text != full_text and para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''

    return new_text

def get_all_paragraphs_with_parents(doc):
    """Get all paragraphs with their parent element reference."""
    result = []

    # Main body paragraphs
    for para in doc.paragraphs:
        result.append((para, doc.element.body))

    # Table paragraphs
    def collect_table_paras(table, parent):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    result.append((para, cell._element))
                for nested_table in cell.tables:
                    collect_table_paras(nested_table, cell._element)

    for table in doc.tables:
        collect_table_paras(table, doc.element.body)

    # Headers and footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            result.append((para, section.header._element))
        for para in section.footer.paragraphs:
            result.append((para, section.footer._element))

    return result

def handle_conditional_relocation(doc, should_include, replacements):
    """
    Handle {{IF_RELOCATION}}...{{END_IF_RELOCATION}} conditional blocks.
    Works across multiple paragraphs.
    """
    start_marker = '{{IF_RELOCATION}}'
    end_marker = '{{END_IF_RELOCATION}}'

    body = doc.element.body
    paragraphs = list(doc.paragraphs)

    # Find start and end paragraph indices
    start_idx = None
    end_idx = None

    for i, para in enumerate(paragraphs):
        text = ''.join(run.text for run in para.runs)
        if start_marker in text:
            start_idx = i
        if end_marker in text:
            end_idx = i

    if start_idx is None or end_idx is None:
        print(f"Warning: Could not find conditional markers. start={start_idx}, end={end_idx}")
        return

    print(f"Found conditional block: paragraphs {start_idx} to {end_idx}")

    if should_include:
        # Keep content, just remove markers
        # Process start paragraph - remove the marker
        start_para = paragraphs[start_idx]
        start_text = ''.join(run.text for run in start_para.runs)
        new_start = start_text.replace(start_marker, '').strip()
        if start_para.runs:
            start_para.runs[0].text = new_start
            for run in start_para.runs[1:]:
                run.text = ''

        # Process end paragraph - remove the marker
        end_para = paragraphs[end_idx]
        end_text = ''.join(run.text for run in end_para.runs)
        new_end = end_text.replace(end_marker, '').strip()
        if end_para.runs:
            end_para.runs[0].text = new_end
            for run in end_para.runs[1:]:
                run.text = ''

        # Replace placeholders in content paragraphs between markers
        for i in range(start_idx + 1, end_idx):
            replace_in_paragraph(paragraphs[i], replacements)

        # Remove empty marker paragraphs if they became empty
        paras_to_remove = []
        if not new_start:
            paras_to_remove.append(paragraphs[start_idx])
        if not new_end and start_idx != end_idx:
            paras_to_remove.append(paragraphs[end_idx])

        for para in paras_to_remove:
            p = para._element
            p.getparent().remove(p)

    else:
        # Remove the entire conditional block including markers
        paras_to_remove = paragraphs[start_idx:end_idx + 1]
        for para in paras_to_remove:
            p = para._element
            p.getparent().remove(p)


def fill_template(template_path, data_path, output_path):
    with open(data_path) as f:
        data = json.load(f)

    doc = Document(template_path)

    relocation_package = data.get('RELOCATION_PACKAGE', 'No').strip().lower()
    should_include_relocation = relocation_package == 'yes'

    print(f"RELOCATION_PACKAGE={data.get('RELOCATION_PACKAGE')}, include={should_include_relocation}")

    # Handle conditional section first (before general replacement)
    handle_conditional_relocation(doc, should_include_relocation, data)

    # Now replace all remaining placeholders in main body
    for para in doc.paragraphs:
        replace_in_paragraph(para, data)

    # Tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_paragraph(para, data)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Headers and footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_paragraph(para, data)
        for para in section.footer.paragraphs:
            replace_in_paragraph(para, data)

    doc.save(output_path)
    print(f"Saved filled offer letter to {output_path}")

    # Verify no placeholders remain
    doc2 = Document(output_path)
    remaining = []
    for para in doc2.paragraphs:
        text = para.text
        matches = re.findall(r'\{\{[^}]+\}\}', text)
        if matches:
            remaining.extend(matches)
    if remaining:
        print(f"WARNING: Unfilled placeholders remain: {remaining}")
    else:
        print("All placeholders filled successfully.")


